turns.prompt:
This function uses a list as a stack to check whether brackets are properly nested. What does it print, and why is each result True or False?

def balanced(s):
    stack = []
    pairs = {")": "(", "]": "["}
    for ch in s:
        if ch in "([":
            stack.append(ch)
        elif stack and stack[-1] == pairs[ch]:
            stack.pop()
        else:
            return False
    return not stack

print(balanced("([])"), balanced("([)]"), balanced("(()"))
